        // ── TSBC (target + actuals merged) ────────────────────
        html += '<tr class="tsbc-row">';
        html += td('TSBC', 'lbl');
        html += td('—', 'num dim'); html += td('—', 'num dim');
        var ttV = isQty ? (ffTargetUnits ? Math.round(ffTargetUnits).toLocaleString() : '—')
                        : (ffTargetRev   ? ('$ ' + ffTargetRev.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})) : '—');
        html += td(ttV, 'num tgt');
        cols.forEach(function (c) {
            var v   = ffProduct ? (isQty ? ((ffProduct.units && ffProduct.units[c]) || 0) : (ffProduct.actuals[c] || 0)) : ((matrix.tsbc_totals && matrix.tsbc_totals[c]) || 0);
            var tgt = ffProduct ? ((ffProduct.cell_targets && ffProduct.cell_targets[c]) || 0) : 0;
            var cls = '';
            if (v > 0 && tgt > 0) { var r = v/tgt; cls = r>=1 ? 'green' : r>=0.7 ? 'amber' : 'red'; }
            html += td(v > 0 ? fmtNum(v) : '—', 'num' + (cls ? ' ' + cls : ''));
        });
        if (showAvg) {
            var ffAvgEx = isQty ? (avgUnits[FF_KEY] || 0) : (avgActuals[FF_KEY] || 0);
            html += td(ffAvgEx > 0 ? fmtNum(ffAvgEx) : '—', 'num');
        }
        html += '</tr>';

        // ── Separator ──────────────────────────────
        html += '<tr class="sep"><td colspan="' + totalCols + '"></td></tr>';

        // ── Master Touch Manufacturing ──────────────
        html += '<tr style="background:#eef2ff;">';
        html += td('Master Touch Manufacturing', 'lbl');
        html += td('—', 'num dim'); html += td('—', 'num dim'); html += td('—', 'num dim');
        cols.forEach(function (c) {
            var v = (matrix.mtm_totals && matrix.mtm_totals[c]) || 0;
            html += td(v > 0 ? fmtNum(v) : '—', 'num');
        });
        if (showAvg) html += td(matrix.avg_mtm > 0 ? fmtNum(matrix.avg_mtm) : '—', 'num');
        html += '</tr>';

        // ── LA Canna ────────────────────────────────
        html += '<tr style="background:#eef2ff;">';
        html += td('LA Canna', 'lbl');
        html += td('—', 'num dim'); html += td('—', 'num dim'); html += td('—', 'num dim');
        cols.forEach(function (c) {
            var v = (matrix.la_canna_totals && matrix.la_canna_totals[c]) || 0;
            html += td(v > 0 ? fmtNum(v) : '—', 'num');
        });
        if (showAvg) html += td(matrix.avg_la_canna > 0 ? fmtNum(matrix.avg_la_canna) : '—', 'num');
        html += '</tr>';

        // ── Separator ──────────────────────────────
        html += '<tr class="sep"><td colspan="' + totalCols + '"></td></tr>';

        // ── Total ───────────────────────────────────
        html += '<tr style="background:#1e293b;color:#fff;font-weight:700;">';
        html += '<td class="lbl" style="color:#fff;padding:7px 12px;">Total</td>';
        html += '<td></td><td></td><td></td>';
        cols.forEach(function (c) {
            var motley  = (matrix.motley_totals   && matrix.motley_totals[c])   || 0;
            var tsbc    = ffProduct ? (ffProduct.actuals[c] || 0) : ((matrix.tsbc_totals && matrix.tsbc_totals[c]) || 0);
            var mtm     = (matrix.mtm_totals      && matrix.mtm_totals[c])      || 0;
            var lacanna = (matrix.la_canna_totals && matrix.la_canna_totals[c]) || 0;
            var total   = motley + tsbc + mtm + lacanna;
            html += '<td style="text-align:right;font-family:Courier New,monospace;padding:7px 12px;color:#fff;">' + (total > 0 ? fmtNum(total) : '—') + '</td>';
        });
        if (showAvg) {
            var avgT = (matrix.avg_motley||0)+(matrix.avg_tsbc||0)+(matrix.avg_mtm||0)+(matrix.avg_la_canna||0);
            html += '<td style="text-align:right;font-family:Courier New,monospace;padding:7px 12px;color:#fff;">' + (avgT > 0 ? fmtNum(avgT) : '—') + '</td>';
        }
        html += '</tr>';

        html += '</table></body></html>';

        // ── Download ──────────────────────────────────────────────
        var blob = new Blob([html], { type: 'application/vnd.ms-excel;charset=utf-8;' });
        var url  = URL.createObjectURL(blob);
        var a    = document.createElement('a');
        a.href   = url;
        a.download = 'Sales_Target_' + periodLabel + '_' + new Date().toISOString().slice(0,10) + '.xls';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    }

    // ── Data loading ──────────────────────────────────────────────
    function loadAll(period) {
        setPeriodUI(period);
        var territory = (rootEl.querySelector('#sd-territory') || {}).value || '';

        ['sd-kpi-target','sd-kpi-actual','sd-kpi-variance','sd-kpi-pending'].forEach(shimmerKpi);
        shimmerEl('sd-matrix');

        frappe.call({
            method: API + 'get_sales_dashboard_data',
            args: { period: period, territory: territory || null },
            callback: function (r) {
                if (!r.message) return;
                var d = r.message, k;
                k = rootEl.querySelector('#sd-kpi-target');
                if (k) { k.textContent = fmtCurrency(d.total_target_rev); k.classList.add('loaded'); }
                k = rootEl.querySelector('#sd-kpi-target-sub');
                if (k) k.textContent = (d.products.length || 0) + ' product line' + (d.products.length !== 1 ? 's' : '') + ' · FY ' + (d.fiscal_year || '—');
                k = rootEl.querySelector('#sd-kpi-actual');
                if (k) { k.textContent = fmtCurrency(d.total_actual_rev); k.classList.add('loaded'); }
                k = rootEl.querySelector('#sd-kpi-actual-sub');
                if (k) k.textContent = d.from_date + ' → ' + d.to_date;
                k = rootEl.querySelector('#sd-kpi-variance');
                if (k) { k.textContent = (d.total_variance >= 0 ? '+' : '') + fmtCurrency(d.total_variance); k.classList.add('loaded'); }
                var vc = rootEl.querySelector('#sd-variance-card');
                if (vc) vc.style.setProperty('--kc', d.on_target ? 'var(--sd-emerald)' : 'var(--sd-rose)');
                k = rootEl.querySelector('#sd-kpi-variance-sub');
                if (k) k.textContent = (d.total_variance_pct >= 0 ? '+' : '') + (d.total_variance_pct || 0).toFixed(1) + '% vs pro-rated target';
                k = rootEl.querySelector('#sd-kpi-pending');
                if (k) { k.textContent = d.pending_invoices || 0; k.classList.add('loaded'); }
            }
        });

        frappe.call({
            method: API + 'get_sales_matrix',
            args: { territory: territory || null },
            callback: function (r) {
                if (!r.message) return;
                matrixCache = {
                    monthly: r.message.monthly,
                    weekly:  r.message.weekly,
                    daily:   r.message.daily,
                };
                renderMatrix('sd-matrix', matrixCache[currentMatrix]);
                if (arMatrixData) {
                    renderArMatrix('sd-ar-matrix', arMatrixData, arMatrixData.columns);
                }
            },
            error: function () {
                var el = rootEl.querySelector('#sd-matrix');
                if (el) el.innerHTML = '<p class="sd-empty">Error loading data.</p>';
            }
        });

        shimmerEl('sd-ar-matrix');
        frappe.call({
            method: API + 'get_ar_matrix',
            callback: function (r) {
                if (!r.message) return;
                arMatrixData = r.message;
                renderArMatrix('sd-ar-matrix', arMatrixData, arMatrixData.columns);
            },
            error: function () {
                var el = rootEl.querySelector('#sd-ar-matrix');
                if (el) el.innerHTML = '<p class="sd-empty">Error loading AR data.</p>';
            }
        });
    }

    function loadTerritories() {
        frappe.call({
            method: API + 'get_sales_territories',
            callback: function (r) {
                var sel = rootEl.querySelector('#sd-territory');
                if (!sel || !r.message || !r.message.length) return;
                r.message.forEach(function (t) {
                    var opt = document.createElement('option');
                    opt.value = opt.textContent = t.name;
                    sel.appendChild(opt);
                });
                sel.value = r.message[0].name;
                loadAll(currentPeriod);
            }
        });
    }

    // ── Event listeners ───────────────────────────────────────────
    rootEl.querySelectorAll('.sd-mtx-btn').forEach(function (btn) {
        btn.addEventListener('click', function () { setMatrixUI(btn.dataset.mtx); });
    });
    rootEl.querySelectorAll('.sd-view-btn').forEach(function (btn) {
        btn.addEventListener('click', function () { setViewUI(btn.dataset.view); });
    });
    rootEl.querySelectorAll('.sd-period-btn').forEach(function (btn) {
        btn.addEventListener('click', function () { currentPeriod = btn.dataset.period; loadAll(currentPeriod); });
    });
    var terrSel = rootEl.querySelector('#sd-territory');
    if (terrSel) terrSel.addEventListener('change', function () { loadAll(currentPeriod); });

    setMatrixUI(currentMatrix);
    setPeriodUI(currentPeriod);
    loadTerritories();
})();

/* ===== INVENTORY SALES DASHBOARD ===== */
(function() {


    // ── state ──
    const S = {
        group: null,
        items: [],
        salesData: {},
        filtered: [],
        expandedRows: new Set(),
        filters: { search:'', warehouse:'__ALL__', onlyAvailable:false, lowStockOnly:false, hasSales:false },
    };

    const LOW = 5;
    const GROUP_WH = { 'Fresh Frozen': 'Hemet TSBC - TSBC' };

    // ── helpers ──
    function esc(s) {
        if (s === null || s === undefined) return '';
        return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;');
    }
    function num(v) { const n = parseFloat(v || 0); return isNaN(n) ? 0 : n; }
    function avail(item) { return num(item.actual_qty) - num(item.reserved_qty); }
    function debounce(fn, ms) {
        let t; return function() { clearTimeout(t); t = setTimeout(() => fn.apply(this, arguments), ms); };
    }
    function isFreshFrozen() { return S.group === 'Fresh Frozen'; }

    function statusBadge(a) {
        if (a <= 0) return '<span class="badge-out">Out of Stock</span>';
        if (a <= LOW) return '<span class="badge-low">Low Stock</span>';
        return '<span class="badge-available">In Stock</span>';
    }

    function rowClass(a) {
        if (a <= 0) return 'row-danger';
        if (a <= LOW) return 'row-warning';
        return '';
    }

    function cleanName(name, group) {
        if (!name) return '—';
        let n = String(name);
        if (group) n = n.replace(new RegExp('\\s*[-]\\s*' + group.replace(/[.*+?^${}()|[\]\\]/g,'\\$&') + '$','i'), '');
        n = n.replace(/_CDC$/i,'').replace(/_[A-Za-z0-9]$/i,'').replace(/_/g,' ').trim();
        return n || String(name);
    }

    function typeLabel(item) {
        const g = String(item.item_group || '');
        if (g === 'Fresh Frozen - BHO') return 'BHO';
        if (g === 'Fresh Frozen - SHO') return 'SHO';
        return '';
    }

    function fmtCurrency(v) {
        return '$' + parseFloat(v || 0).toLocaleString('en-US', { minimumFractionDigits:2, maximumFractionDigits:2 });
    }

    // ── group loading ──
    function loadGroups() {
        frappe.call({
            method: 'cannabis_management.cannabis_management.page.inventory_sales_dashboard.inventory_sales_dashboard.get_item_groups',
            callback: function(r) {
                if (r && r.message && r.message.length) {
                    renderGroups(sortGroups(filterSubgroups(r.message)));
                } else {
                    root_element.getElementById('isd-group-list').innerHTML = '<div class="isd-empty" style="padding:20px">No groups found</div>';
                }
            },
            error: function() {
                root_element.getElementById('isd-group-list').innerHTML = '<div class="isd-empty" style="padding:20px">Could not load groups</div>';
            }
        });
    }

    const GROUP_ORDER = ['Fresh Frozen','Primes','Subprimes','VRR','O2 Vape','1g O2 Vapes','LIQUID LIVE RESIN','Full Spec','Food Grade','Gummies','Farm Supplies','Drawings'];

    function filterSubgroups(groups) {
        return groups.filter(g => g.name !== 'Fresh Frozen - BHO' && g.name !== 'Fresh Frozen - SHO');
    }

    function sortGroups(groups) {
        return groups.sort((a, b) => {
            const ia = GROUP_ORDER.findIndex(x => x.toLowerCase() === a.name.toLowerCase());
            const ib = GROUP_ORDER.findIndex(x => x.toLowerCase() === b.name.toLowerCase());
            if (ia !== -1 && ib !== -1) return ia - ib;
            if (ia !== -1) return -1;
            if (ib !== -1) return 1;
            return a.name.localeCompare(b.name);
        });
    }

    function renderGroups(groups) {
        let html = '';
        groups.forEach(g => {
            html += `<div class="isd-group-btn" data-group="${esc(g.name)}">
                <span>${esc(g.name)}</span>
                <span class="isd-group-count">${g.item_count || ''}</span>
            </div>`;
        });
        const el = root_element.getElementById('isd-group-list');
        el.innerHTML = html;
        el.querySelectorAll('.isd-group-btn').forEach(btn => {
            btn.addEventListener('click', function() { loadStock(this.dataset.group); });
        });
    }

    // ── stock loading ──
    function loadStock(group) {
        S.group = group;
        S.items = [];
        S.salesData = {};
        S.filtered = [];
        S.expandedRows = new Set();

        root_element.getElementById('isd-selected-group').innerHTML = `
            <svg width="18" height="18" fill="none" stroke="#2563EB" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" viewBox="0 0 24 24" style="flex-shrink:0"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/><polyline points="3.27 6.96 12 12.01 20.73 6.96"/><line x1="12" y1="22.08" x2="12" y2="12"/></svg>
            ${esc(group)}
        `;
        root_element.getElementById('isd-table-wrap').innerHTML = `
            <div class="isd-loading">
                <div class="isd-spinner"></div>
                <div class="isd-loading-text">Loading stock and sales data…</div>
            </div>`;
        setSummary([], {});

        root_element.querySelectorAll('.isd-group-btn').forEach(b => {
            b.classList.toggle('active', b.dataset.group === group);
        });

        frappe.call({
            method: 'cannabis_management.cannabis_management.page.inventory_sales_dashboard.inventory_sales_dashboard.get_stock_with_sales',
            args: { item_group: group },
            callback: function(r) {
                if (r && r.message) {
                    S.items = r.message.items || [];
                    S.salesData = r.message.sales_data || {};
                } else {
                    S.items = [];
                    S.salesData = {};
                }
                resetFilters();
                applyFilters();
            },
            error: function() {
                root_element.getElementById('isd-table-wrap').innerHTML = `
                    <div class="isd-empty">
                        <div class="isd-empty-icon">⚠️</div>
                        Could not load data. Please try again.
                    </div>`;
            }
        });
    }

    // ── filters ──
    function resetFilters() {
        S.filters = { search:'', warehouse:'__ALL__', onlyAvailable:false, lowStockOnly:false, hasSales:false };
        root_element.getElementById('isd-search').value = '';
        root_element.getElementById('isd-only-available').checked = false;
        root_element.getElementById('isd-low-stock-only').checked = false;
        root_element.getElementById('isd-has-sales').checked = false;
    }

    function applyFilters() {
        if (!S.items.length) {
            S.filtered = [];
            setSummary([], {});
            populateWh([]);
            root_element.getElementById('isd-table-wrap').innerHTML = `
                <div class="isd-empty">
                    <div class="isd-empty-icon">🔍</div>
                    No items found for this group
                </div>`;
            return;
        }

        const warehouses = [...new Set(S.items.map(i => i.warehouse).filter(Boolean))].sort();
        populateWh(warehouses);

        S.filtered = S.items.filter(item => {
            const a = avail(item);
            const name = cleanName(item.item_name, item.item_group || S.group).toLowerCase();
            const code = (item.item_code || '').toLowerCase();
            const q = S.filters.search;
            if (S.filters.warehouse !== '__ALL__' && item.warehouse !== S.filters.warehouse) return false;
            if (q && !code.includes(q) && !name.includes(q)) return false;
            if (S.filters.onlyAvailable && a <= 0) return false;
            if (S.filters.lowStockOnly && !(a > 0 && a <= LOW)) return false;
            if (S.filters.hasSales && !S.salesData[item.item_code]) return false;
            return true;
        });

        setSummary(S.filtered, S.salesData);
        renderTable(S.filtered);
    }

    function populateWh(warehouses) {
        let html = '<option value="__ALL__">All Warehouses</option>';
        warehouses.forEach(w => html += `<option value="${esc(w)}">${esc(w)}</option>`);
        const el = root_element.getElementById('isd-warehouse');
        el.innerHTML = html;
        el.value = warehouses.includes(S.filters.warehouse) ? S.filters.warehouse : '__ALL__';
    }

    // ── summary ──
    function setSummary(items) {
        let totalQty = 0, totalAvail = 0, low = 0;
        items.forEach(i => {
            const a = avail(i);
            totalQty += num(i.actual_qty);
            totalAvail += a;
            if (a > 0 && a <= LOW) low++;
        });
        root_element.getElementById('isd-total-items').textContent = items.length;
        root_element.getElementById('isd-total-qty').textContent   = totalQty.toFixed(2);
        root_element.getElementById('isd-avail-qty').textContent   = totalAvail.toFixed(2);
        root_element.getElementById('isd-low-stock').textContent   = low;
    }

    // ── table ──
    function renderTable(items) {
        if (!items.length) {
            root_element.getElementById('isd-table-wrap').innerHTML = `
                <div class="isd-empty">
                    <div class="isd-empty-icon">🔍</div>
                    No items match the current filters
                </div>`;
            return;
        }

        const ff = isFreshFrozen();
        const colspan = ff ? 9 : 8;

        let html = `<table class="isd-table"><thead><tr>
            <th style="width:42px"></th>
            <th>Item Code</th>
            <th>Item Name</th>
            ${ff ? '<th>Type</th>' : ''}
            <th>Warehouse</th>
            <th style="text-align:right">Qty</th>
            <th style="text-align:right">Reserved</th>
            <th style="text-align:right">Available</th>
            <th>Status</th>
        </tr></thead><tbody>`;

        items.forEach((item, idx) => {
            const a = avail(item);
            const rc = rowClass(a);
            const tl = typeLabel(item);
            const codeJson = JSON.stringify(String(item.item_code || ''));
            const arrowCls = expandArrowClass(S.salesData[item.item_code]);

            html += `
            <tr class="${rc}" data-idx="${idx}">
                <td class="isd-expand-td ${arrowCls}" data-idx="${idx}" title="View Delivery Notes &amp; Invoices">
                    <span class="isd-expand-arrow">&#9654;</span>
                </td>
                <td>
                    <div class="isd-code-cell">
                        <span class="isd-code-text">${esc(item.item_code || '')}</span>
                        <button class="isd-copy-btn" onclick='isdCopy(${codeJson})'>Copy</button>
                    </div>
                </td>
                <td class="isd-item-name">${esc(cleanName(item.item_name, item.item_group || S.group))}</td>
                ${ff ? `<td>${tl ? `<span class="badge-type-${tl.toLowerCase()}">${esc(tl)}</span>` : ''}</td>` : ''}
                <td>${item.warehouse ? `<span class="isd-wh-text">${esc(item.warehouse)}</span>` : '<span class="isd-wh-none">— No Stock —</span>'}</td>
                <td style="text-align:right"><span class="isd-num">${num(item.actual_qty).toFixed(2)}</span></td>
                <td style="text-align:right"><span class="isd-num">${num(item.reserved_qty).toFixed(2)}</span></td>
                <td style="text-align:right"><span class="isd-num-avail">${a.toFixed(2)}</span></td>
                <td>${statusBadge(a)}</td>
            </tr>
            <tr class="expand-row" id="expand-${idx}" style="display:none">
                <td colspan="${colspan}">
                    <div class="isd-expand-panel" id="expand-body-${idx}"></div>
                </td>
            </tr>`;
        });

        html += '</tbody></table>';
        root_element.getElementById('isd-table-wrap').innerHTML = html;
    }

    function expandArrowClass(entries) {
        if (!entries || !entries.length) return 'no-data';
        const needsAttention = entries.some(e =>
            e.sale_status === 'delivered_not_invoiced' ||
            e.sale_status === 'partially_invoiced' ||
            e.sale_status === 'delivered_invoiced_unlinked'
        );
        return needsAttention ? 'needs-invoice' : 'has-activity';
    }

    function toggleExpand(idx, td) {
        const expandRow = root_element.getElementById(`expand-${idx}`);
        const body      = root_element.getElementById(`expand-body-${idx}`);
        if (!expandRow || (td && td.classList.contains('no-data'))) return;

        if (S.expandedRows.has(idx)) {
            S.expandedRows.delete(idx);
            expandRow.style.display = 'none';
            if (td) td.classList.remove('expanded');
        } else {
            S.expandedRows.add(idx);
            expandRow.style.display = '';
            if (td) td.classList.add('expanded');
            body.innerHTML = buildExpandPanel(S.filtered[idx]);
        }
    }

    // ── expand panel builders ──
    function buildExpandPanel(item) {
        const entries = S.salesData[item.item_code];
        if (!entries || !entries.length) {
            return `<div class="isd-no-activity-msg">No delivery notes or sales invoices found for <strong>${esc(item.item_code)}</strong>.</div>`;
        }

        let html = `<div class="isd-expand-heading">Sales &amp; Delivery history for ${esc(item.item_code)}</div>`;

        entries.forEach(entry => {
            const { hdrCls, badgeCls } = statusStyles(entry.sale_status);
            html += `
            <div class="isd-customer-block">
                <div class="isd-customer-header ${hdrCls}">
                    <span class="isd-customer-name">
                        <span class="isd-cust-icon">🏢</span>
                        ${esc(entry.customer)}
                    </span>
                    <span class="isd-sale-status-badge ${badgeCls}">${saleStatusLabel(entry.sale_status)}</span>
                </div>
                <div class="isd-customer-body">
                    ${buildAlertMsg(entry)}
                    ${buildDNSection(entry.delivery_notes)}
                    ${buildDirectSection(entry.direct_invoices)}
                </div>
            </div>`;
        });

        return html;
    }

    function buildDNSection(dns) {
        if (!dns || !dns.length) return '';
        let html = '<div class="isd-section-title">Delivery Notes</div>';
        dns.forEach(dn => {
            html += `
            <div class="isd-dn-card">
                <div class="isd-dn-top">
                    <a class="isd-doc-link" href="/app/delivery-note/${esc(dn.name)}" target="_blank">${esc(dn.name)}</a>
                    <span class="isd-pill isd-pill-blue">📅 ${esc(dn.date)}</span>
                    <span class="isd-pill isd-pill-gray">Qty: ${num(dn.qty).toFixed(2)} ${esc(dn.uom)}</span>
                    <span class="isd-pill ${dn.dn_status === 'Delivered' ? 'isd-pill-green' : 'isd-pill-orange'}">${esc(dn.dn_status)}</span>
                </div>
                ${buildLinkedInvoices(dn.invoices, dn.name)}
            </div>`;
        });
        return html;
    }

    function buildLinkedInvoices(invoices, dnName) {
        if (!invoices || !invoices.length) {
            return `<div class="isd-no-invoice-msg">
                <span>⚠️</span>
                <span>Product delivered (<strong>${esc(dnName)}</strong>) — no Sales Invoice has been generated yet for this customer.</span>
            </div>`;
        }
        let html = `<div class="isd-si-list">
            <div class="isd-si-list-title">Linked Sales Invoices</div>`;
        invoices.forEach(inv => {
            const paid = inv.outstanding <= 0;
            html += `
            <div class="isd-si-row">
                <a class="isd-si-link" href="/app/sales-invoice/${esc(inv.name)}" target="_blank">${esc(inv.name)}</a>
                <span class="isd-pill isd-pill-blue">📅 ${esc(inv.date)}</span>
                <span class="isd-si-amount">Total: ${fmtCurrency(inv.total)}</span>
                <span class="${paid ? 'isd-outstanding-ok' : 'isd-outstanding-due'}">
                    ${paid ? '✓ Paid' : `Outstanding: ${fmtCurrency(inv.outstanding)}`}
                </span>
                <span class="isd-pill ${paid ? 'isd-pill-green' : 'isd-pill-orange'}">${esc(inv.status)}</span>
            </div>`;
        });
        html += '</div>';
        return html;
    }

    function buildDirectSection(invoices) {
        if (!invoices || !invoices.length) return '';
        let html = `<div class="isd-direct-section">
            <div class="isd-section-title">Direct Sales Invoices <span style="font-size:10px;color:#94A3B8;font-weight:normal;text-transform:none;letter-spacing:0">(no delivery note)</span></div>`;
        invoices.forEach(inv => {
            const paid = inv.outstanding <= 0;
            html += `
            <div class="isd-si-row">
                <a class="isd-si-link" href="/app/sales-invoice/${esc(inv.name)}" target="_blank">${esc(inv.name)}</a>
                <span class="isd-pill isd-pill-blue">📅 ${esc(inv.date)}</span>
                <span class="isd-si-amount">Total: ${fmtCurrency(inv.total)}</span>
                <span class="${paid ? 'isd-outstanding-ok' : 'isd-outstanding-due'}">
                    ${paid ? '✓ Paid' : `Outstanding: ${fmtCurrency(inv.outstanding)}`}
                </span>
                <span class="isd-pill ${paid ? 'isd-pill-green' : 'isd-pill-orange'}">${esc(inv.status)}</span>
            </div>`;
        });
        html += '</div>';
        return html;
    }

    function buildAlertMsg(entry) {
        const dnCount  = (entry.delivery_notes || []).length;
        const invCount = (entry.delivery_notes || []).reduce((s, d) => s + (d.invoices || []).length, 0);
        const dCount   = (entry.direct_invoices || []).length;
        const map = {
            fully_invoiced: [
                'isd-alert-ok', '✅',
                `All ${dnCount} delivery note${dnCount!==1?'s':''} have been invoiced. Product delivered and fully billed.`
            ],
            partially_invoiced: [
                'isd-alert-warn', '⚠️',
                `${dnCount} delivery note${dnCount!==1?'s':''} on record — only ${invCount} ${invCount!==1?'are':'is'} linked to an invoice. Some deliveries are not yet billed.`
            ],
            delivered_not_invoiced: [
                'isd-alert-warn', '⚠️',
                `Product has been delivered (${dnCount} DN${dnCount!==1?'s':''}) but no Sales Invoice has been generated for this customer. Action required.`
            ],
            delivered_invoiced_unlinked: [
                'isd-alert-warn', '🔗',
                `A Delivery Note and ${dCount} Sales Invoice${dCount!==1?'s':''} both exist for this customer, but the invoice${dCount!==1?'s were':' was'} created separately and ${dCount!==1?'are':'is'} not linked to the Delivery Note. Please verify this is correct or link them in ERPNext.`
            ],
            invoiced_direct: [
                'isd-alert-info', 'ℹ️',
                'Customer was invoiced directly — no Delivery Note was recorded for this transaction.'
            ],
            no_activity: ['', '', ''],
        };
        const [cls, icon, msg] = map[entry.sale_status] || ['','',''];
        if (!msg) return '';
        return `<div class="isd-alert-msg ${cls}"><span class="isd-alert-icon">${icon}</span><span>${msg}</span></div>`;
    }

    function saleStatusLabel(s) {
        return {
            fully_invoiced:              'Delivered & Invoiced',
            partially_invoiced:          'Partially Invoiced',
            delivered_not_invoiced:      'Invoice Pending',
            delivered_invoiced_unlinked: 'Invoice Not Linked',
            invoiced_direct:             'Invoiced (No DN)',
            no_activity:                 'No Activity',
        }[s] || s;
    }

    function statusStyles(s) {
        const m = {
            fully_invoiced:              { hdrCls:'isd-ch-fully',    badgeCls:'isd-sb-fully'    },
            partially_invoiced:          { hdrCls:'isd-ch-partial',  badgeCls:'isd-sb-partial'  },
            delivered_not_invoiced:      { hdrCls:'isd-ch-notinv',   badgeCls:'isd-sb-notinv'   },
            delivered_invoiced_unlinked: { hdrCls:'isd-ch-unlinked', badgeCls:'isd-sb-unlinked' },
            invoiced_direct:             { hdrCls:'isd-ch-direct',   badgeCls:'isd-sb-direct'   },
            no_activity:                 { hdrCls:'isd-ch-none',     badgeCls:'isd-sb-none'     },
        };
        return m[s] || m.no_activity;
    }

    // ── events ──
    root_element.getElementById('isd-table-wrap').addEventListener('click', function(e) {
        const td = e.target.closest('.isd-expand-td');
        if (td) toggleExpand(parseInt(td.dataset.idx), td);
    });

    const searchEl = root_element.getElementById('isd-search');
    const whEl     = root_element.getElementById('isd-warehouse');
    const availEl  = root_element.getElementById('isd-only-available');
    const lowEl    = root_element.getElementById('isd-low-stock-only');
    const salesEl  = root_element.getElementById('isd-has-sales');
    const resetBtn = root_element.getElementById('isd-reset-btn');
    const exportBtn= root_element.getElementById('isd-export-btn');

    searchEl.addEventListener('input',  debounce(function() { S.filters.search = this.value.trim().toLowerCase(); applyFilters(); }, 200));
    whEl.addEventListener('change',     function() { S.filters.warehouse     = this.value;   applyFilters(); });
    availEl.addEventListener('change',  function() { S.filters.onlyAvailable = this.checked; applyFilters(); });
    lowEl.addEventListener('change',    function() { S.filters.lowStockOnly  = this.checked; applyFilters(); });
    salesEl.addEventListener('change',  function() { S.filters.hasSales      = this.checked; applyFilters(); });
    resetBtn.addEventListener('click',  function() { resetFilters(); applyFilters(); });
    exportBtn.addEventListener('click', exportCSV);

    root_element.getElementById('isd-sidebar-toggle').addEventListener('click', function() {
        const gl = root_element.getElementById('isd-group-list');
        gl.style.display = gl.style.display === 'none' ? '' : 'none';
    });

    // ── CSV export ──
    function exportCSV() {
        if (!S.filtered.length) { frappe.show_alert({ message:'No rows to export', indicator:'orange' }); return; }
        const ff = isFreshFrozen();
        const rows = [['Item Code','Item Name',...(ff?['Type']:[]),'Warehouse','Qty','Reserved','Available','Status','Sale Status','Customers']];
        S.filtered.forEach(item => {
            const a = avail(item);
            const entries = S.salesData[item.item_code] || [];
            rows.push([
                item.item_code || '',
                cleanName(item.item_name, item.item_group || S.group),
                ...(ff ? [typeLabel(item)] : []),
                item.warehouse || '',
                num(item.actual_qty).toFixed(2),
                num(item.reserved_qty).toFixed(2),
                a.toFixed(2),
                a<=0 ? 'Out of Stock' : a<=LOW ? 'Low Stock' : 'Available',
                entries.map(e => saleStatusLabel(e.sale_status)).join('; ') || 'No Activity',
                entries.map(e => e.customer).join('; '),
            ]);
        });
        const csv  = rows.map(r => r.map(v => '"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n');
        const blob = new Blob([csv], { type:'text/csv;charset=utf-8;' });
        const url  = URL.createObjectURL(blob);
        const a    = document.createElement('a');
        a.href = url;
        a.download = (S.group||'inventory').replace(/\s+/g,'_') + '_sales.csv';
        document.body.appendChild(a); a.click(); document.body.removeChild(a);
        URL.revokeObjectURL(url);
        frappe.show_alert({ message:'CSV exported', indicator:'green' });
    }

    // ── init ──
    loadGroups();

    window.isdCopy = function(text) {
        if (!text) return;
        (navigator.clipboard ? navigator.clipboard.writeText(text) : Promise.reject())
            .then(() => frappe.show_alert({ message:'Copied: '+text, indicator:'green' }))
            .catch(() => {
                const t = document.createElement('input');
                t.value = text; document.body.appendChild(t); t.select();
                try { document.execCommand('copy'); frappe.show_alert({ message:'Copied: '+text, indicator:'green' }); } catch(e){}
                document.body.removeChild(t);
            });
    };
})();

/* ===== SALES DAILY SYNC — TOP SECTIONS JS ===== */
(function() {
  var API = "cannabis_management.api.sales_daily_sync.";

  function q(id) { return root_element.querySelector('#' + id); }
  function esc(s) {
    if (s === null || s === undefined) return '';
    return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }
  function money(n) {
    n = parseFloat(n || 0);
    var neg = n < 0;
    var s = '$' + Math.abs(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    return neg ? '-' + s : s;
  }
  function fmtDate(d) {
    if (!d) return '—';
    var p = String(d).split(' ')[0].split('-');
    return p.length === 3 ? p[1] + '/' + p[2] + '/' + p[0] : d;
  }

  function loadCod() {
    frappe.call({
      method: API + 'get_cod_deliveries_last_7_days',
      callback: function(r) {
        if (!r || !r.message) return;
        var d = r.message;
        var dl = q('sds-cod-date'); if (dl) dl.textContent = fmtDate(d.from_date) + ' – ' + fmtDate(d.to_date);
        var tb = q('sds-cod-total');
        if (tb) tb.textContent = money(d.total) + ' · ' + d.count + ' order' + (d.count !== 1 ? 's' : '');
        var wrap = q('sds-cod-table'); if (!wrap) return;
        if (!d.rows.length) { wrap.innerHTML = '<div class="sds-empty">No COD orders shipped in the last 7 days.</div>'; return; }
        var h = '<table class="sds-tbl"><thead><tr><th>Order</th><th>Customer</th><th class="sds-r">Amount</th></tr></thead><tbody>';
        d.rows.forEach(function(row) {
          h += '<tr><td>'
             + '<a class="sds-link" href="/app/delivery-note/' + esc(row.delivery_note) + '" target="_blank">' + esc(row.delivery_note) + '</a>'
             + '<div class="sds-muted">' + fmtDate(row.date) + (row.sales_order ? ' · SO: ' + esc(row.sales_order) : '') + '</div>'
             + '</td><td>' + esc(row.customer) + '</td>'
             + '<td class="sds-r sds-mono">' + money(row.amount) + '</td></tr>';
        });
        h += '</tbody></table>';
        wrap.innerHTML = h;
      },
      error: function() { var w = q('sds-cod-table'); if (w) w.innerHTML = '<div class="sds-empty">Could not load.</div>'; }
    });
  }

  function loadPva() {
    frappe.call({
      method: API + 'get_predicted_vs_actual',
      callback: function(r) {
        if (!r || !r.message) return;
        var d = r.message;
        var e = q('sds-exp-total'); if (e) e.textContent = money(d.expected_total);
        var rc = q('sds-rcv-total'); if (rc) rc.textContent = money(d.received_total);
        var pd = q('sds-pva-date'); if (pd) pd.textContent = fmtDate(d.from_date) + ' – ' + fmtDate(d.to_date);
        var wrap = q('sds-pva-table'); if (!wrap) return;
        if (!d.rows.length) { wrap.innerHTML = '<div class="sds-empty">No outstanding invoices in the last 7 days.</div>'; return; }
        var h = '<table class="sds-tbl"><thead><tr><th>Reference</th><th class="sds-r">Expected</th><th class="sds-r">Received</th></tr></thead><tbody>';
        d.rows.forEach(function(row) {
          var full = row.expected > 0 && row.received >= row.expected;
          h += '<tr><td>'
             + '<a class="sds-link" href="/app/sales-invoice/' + esc(row.reference) + '" target="_blank">' + esc(row.reference) + '</a>'
             + '<div class="sds-muted">' + esc(row.customer) + ' · ' + fmtDate(row.date) + '</div>'
             + '</td>'
             + '<td class="sds-r sds-mono">' + money(row.expected) + '</td>'
             + '<td class="sds-r sds-mono ' + (full ? 'sds-pos' : 'sds-neg') + '">' + money(row.received) + '</td></tr>';
        });
        h += '</tbody></table>';
        wrap.innerHTML = h;
      },
      error: function() { var w = q('sds-pva-table'); if (w) w.innerHTML = '<div class="sds-empty">Could not load.</div>'; }
    });
  }

  loadCod();
  loadPva();
})();

/* ===== AR DASHBOARD SECTION JS ===== */
(function() {
  var SUMMARY_API   = "cannabis_management.api.sales_daily_sync.get_ar_week_summary";
  var COMPANIES_API = "cannabis_management.api.sales_daily_sync.get_ar_companies";
  var DEFAULT_COMPANY = "Motley Terpz";   // matches the AR Dashboard page default

  function q(id) { return root_element.querySelector('#' + id); }
  function money(n) {
    n = parseFloat(n || 0);
    var neg = n < 0;
    var s = '$' + Math.abs(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    return neg ? '-' + s : s;
  }
  function fmtDate(d) {
    if (!d) return '—';
    var p = String(d).split(' ')[0].split('-');
    return p.length === 3 ? p[1] + '/' + p[2] + '/' + p[0] : d;
  }
  function shimmer() {
    ['ars-legacy-bal','ars-legacy-coll','ars-new-acc','ars-paid'].forEach(function(id){
      var el = q(id); if (el) el.textContent = '…';
    });
  }

  function load(company) {
    shimmer();
    frappe.call({
      method: SUMMARY_API,
      args: { company: company },
      callback: function(r) {
        if (!r || !r.message) return;
        var d = r.message;
        var w = q('ars-week'); if (w) w.textContent = fmtDate(d.week_start) + ' – ' + fmtDate(d.week_end);
        var a = q('ars-legacy-bal'); if (a) a.textContent = money(d.legacy_ar_balance);
        var b = q('ars-legacy-coll'); if (b) b.textContent = money(d.legacy_collected_week);
        var c = q('ars-new-acc'); if (c) c.textContent = money(d.post_legacy_accumulated_week);
        var e = q('ars-paid'); if (e) e.textContent = money(d.ar_paid_down_week);
      }
    });
  }

  // Populate the company dropdown, then load the default company.
  frappe.call({
    method: COMPANIES_API,
    callback: function(r) {
      var sel = q('ars-company');
      var companies = (r && r.message) || [];
      if (sel) {
        companies.forEach(function(co) {
          var opt = document.createElement('option');
          opt.value = opt.textContent = co;
          sel.appendChild(opt);
        });
        var initial = companies.indexOf(DEFAULT_COMPANY) !== -1 ? DEFAULT_COMPANY : (companies[0] || '');
        sel.value = initial;
        sel.addEventListener('change', function() { load(this.value); });
        load(initial);
      } else {
        load(DEFAULT_COMPANY);
      }
    },
    error: function() { load(DEFAULT_COMPANY); }
  });
})();

/* ===== UNRECONCILED CUSTOMERS SECTION JS ===== */
(function() {
  var SUMMARY_API   = "cannabis_management.api.sales_daily_sync.get_unreconciled_customers";
  var COMPANIES_API = "cannabis_management.api.sales_daily_sync.get_ar_companies";
  var DEFAULT_COMPANY = "Motley Terpz";

  function q(id) { return root_element.querySelector('#' + id); }
  function esc(s) {
    if (s === null || s === undefined) return '';
    return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }
  function money(n) {
    n = parseFloat(n || 0);
    var neg = n < 0;
    var s = '$' + Math.abs(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    return neg ? '-' + s : s;
  }
  function fmtDate(d) {
    if (!d) return '—';
    var p = String(d).split(' ')[0].split('-');
    return p.length === 3 ? p[1] + '/' + p[2] + '/' + p[0] : d;
  }

  function renderTrend(d) {
    var el = q('urc-trend'); if (!el) return;
    if (d.prev_count === null || d.prev_count === undefined) {
      el.className = 'urc-kpi-trend'; el.textContent = 'baseline set today · trend builds from tomorrow';
      return;
    }
    var diff = d.count - d.prev_count;
    var since = ' since ' + fmtDate(d.prev_date);
    if (diff < 0)      { el.className = 'urc-kpi-trend urc-trend-down'; el.textContent = '▼ ' + Math.abs(diff) + ' fewer' + since + ' (shrinking)'; }
    else if (diff > 0) { el.className = 'urc-kpi-trend urc-trend-up';   el.textContent = '▲ ' + diff + ' more' + since + ' — worth a conversation'; }
    else               { el.className = 'urc-kpi-trend urc-trend-flat'; el.textContent = 'No change' + since; }
    if (d.week_start_count !== null && d.week_start_count !== undefined) {
      var wd = d.count - d.week_start_count;
      el.textContent += ' · ' + (wd <= 0 ? '▼ ' + Math.abs(wd) : '▲ ' + wd) + ' vs start of week';
    }
  }

  function load(company) {
    var wrap = q('urc-table');
    if (wrap) wrap.innerHTML = '<div class="urc-loading"><div class="urc-spin"></div></div>';
    frappe.call({
      method: SUMMARY_API,
      args: { company: company },
      callback: function(r) {
        if (!r || !r.message) return;
        var d = r.message;
        var ao = q('urc-asof'); if (ao) ao.textContent = fmtDate(d.as_of);
        var cnt = q('urc-count'); if (cnt) cnt.textContent = (d.count || 0).toLocaleString();
        renderTrend(d);
        if (!wrap) return;
        if (!d.rows.length) { wrap.innerHTML = '<div class="urc-empty">No unreconciled customers for this company.</div>'; return; }
        var h = '<table class="urc-tbl"><thead><tr><th>Customer</th><th class="urc-r">Invoiced</th><th class="urc-r">Paid</th><th class="urc-r">Outstanding</th></tr></thead><tbody>';
        var ti = 0, tp = 0, to = 0;
        d.rows.forEach(function(row) {
          ti += row.invoiced; tp += row.paid; to += row.outstanding;
          h += '<tr><td><span class="urc-cust">' + esc(row.customer_name) + '</span>'
             + '<div class="urc-muted">' + (row.invoice_count || 0) + ' invoice' + (row.invoice_count !== 1 ? 's' : '') + '</div></td>'
             + '<td class="urc-r urc-mono">' + money(row.invoiced) + '</td>'
             + '<td class="urc-r urc-mono">' + money(row.paid) + '</td>'
             + '<td class="urc-r urc-mono urc-out">' + money(row.outstanding) + '</td></tr>';
        });
        h += '</tbody><tfoot><tr><td class="urc-tfoot">Total · ' + d.rows.length + ' customers</td>'
           + '<td class="urc-tfoot urc-r urc-mono">' + money(ti) + '</td>'
           + '<td class="urc-tfoot urc-r urc-mono">' + money(tp) + '</td>'
           + '<td class="urc-tfoot urc-r urc-mono urc-out">' + money(to) + '</td></tr></tfoot></table>';
        wrap.innerHTML = h;
      },
      error: function() { if (wrap) wrap.innerHTML = '<div class="urc-empty">Could not load.</div>'; }
    });
  }

  frappe.call({
    method: COMPANIES_API,
    callback: function(r) {
      var sel = q('urc-company');
      var companies = (r && r.message) || [];
      if (sel) {
        companies.forEach(function(co) {
          var opt = document.createElement('option');
          opt.value = opt.textContent = co;
          sel.appendChild(opt);
        });
        var initial = companies.indexOf(DEFAULT_COMPANY) !== -1 ? DEFAULT_COMPANY : (companies[0] || '');
        sel.value = initial;
        sel.addEventListener('change', function() { load(this.value); });
        load(initial);
      } else { load(DEFAULT_COMPANY); }
    },
    error: function() { load(DEFAULT_COMPANY); }
  });
})();

