/* ===== INVENTORY SALES DASHBOARD CSS ===== */
/* ═══════════════════════════════════════════════════
   INVENTORY SALES DASHBOARD — STYLES
═══════════════════════════════════════════════════ */

/* base */
.isd-wrap {
    padding:0;
    font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;
    background:#F1F5F9;
    min-height:calc(100vh - 60px);
}

/* ── header ── */
.isd-header {
    background:linear-gradient(135deg,#1E3A8A 0%,#2563EB 60%,#3B82F6 100%);
    padding:18px 24px;
    display:flex;
    align-items:center;
    justify-content:space-between;
    flex-wrap:wrap;
    gap:12px;
}
.isd-header-left { display:flex; align-items:center; gap:14px; }
.isd-header-icon {
    width:44px; height:44px;
    background:rgba(255,255,255,.18);
    border-radius:12px;
    display:flex; align-items:center; justify-content:center;
    flex-shrink:0;
}
.isd-title  { font-size:19px; font-weight:700; color:#fff; margin:0 0 3px; line-height:1.2; }
.isd-subtitle { color:rgba(255,255,255,.75); font-size:12px; margin:0; }
.isd-btn-export {
    background:rgba(255,255,255,.15);
    color:#fff;
    border:1.5px solid rgba(255,255,255,.3);
    border-radius:8px;
    padding:8px 18px;
    font-size:13px;
    font-weight:500;
    cursor:pointer;
    display:flex; align-items:center; gap:6px;
    transition:background .15s;
    white-space:nowrap;
}
.isd-btn-export:hover { background:rgba(255,255,255,.28); }

/* ── body grid ── */
.isd-body {
    display:grid;
    grid-template-columns:220px 1fr;
    min-height:calc(100vh - 130px);
}
@media(max-width:900px){ .isd-body{ grid-template-columns:1fr; } }

/* ── sidebar ── */
.isd-sidebar {
    background:#fff;
    border-right:1px solid #E2E8F0;
}
.isd-sidebar-header {
    padding:12px 16px;
    font-size:10px;
    font-weight:700;
    letter-spacing:.8px;
    text-transform:uppercase;
    color:#94A3B8;
    border-bottom:1px solid #F1F5F9;
    background:#FAFBFC;
    display:flex; justify-content:space-between; align-items:center;
    cursor:pointer;
