}
.isd-group-list { padding:6px 0; overflow-y:auto; max-height:calc(100vh - 180px); }
.isd-group-btn {
    padding:9px 16px 9px 14px;
    cursor:pointer;
    font-size:13px;
    font-weight:500;
    color:#475569;
    transition:all .13s;
    white-space:nowrap;
    overflow:hidden;
    text-overflow:ellipsis;
    border-left:3px solid transparent;
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap:6px;
}
.isd-group-btn:hover { background:#F0F7FF; color:#2563EB; border-left-color:#93C5FD; }
.isd-group-btn.active {
    background:#EFF6FF;
    color:#1D4ED8;
    font-weight:600;
    border-left-color:#2563EB;
}
.isd-group-count {
    font-size:10px;
    background:#E2E8F0;
    color:#64748B;
    border-radius:10px;
    padding:1px 6px;
    font-weight:600;
    flex-shrink:0;
}
.isd-group-btn.active .isd-group-count { background:#DBEAFE; color:#1D4ED8; }

/* ── main panel ── */
.isd-main { padding:20px; display:flex; flex-direction:column; gap:16px; }

/* ── group title bar ── */
.isd-group-title-bar {
    display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:8px;
}
.isd-group-title {
    font-size:18px;
    font-weight:700;
    color:#0F172A;
    margin:0;
    display:flex;
    align-items:center;
    gap:10px;
}
.isd-group-pill {
    background:#EFF6FF;
    color:#2563EB;
